cat > src/parse.js <<'EOF'
const NAME = /^[A-Za-z0-9_-]+$/
const fail = (msg) => Object.assign(new Error(msg), { election: true })

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  lines.forEach((raw, i) => {
    const n = i + 1
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const [word, ...args] = line.split(/\s+/)
    if (word === 'candidates') {
      if (candidates !== null || ballots.length > 0) fail0(n, 'candidates must be declared once, before any ballot')
      if (args.length === 0) fail0(n, 'expected candidates <name>...')
      const seen = new Set()
      for (const a of args) {
        if (!NAME.test(a)) fail0(n, `invalid candidate name ${a}`)
        if (seen.has(a)) fail0(n, `candidate ${a} is declared twice`)
        seen.add(a)
      }
      candidates = args
    } else if (word === 'ballot') {
      if (candidates === null) fail0(n, 'candidates must be declared once, before any ballot')
      if (args.length < 2) fail0(n, 'expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(args[0])) fail0(n, 'count must be a positive integer')
      const seen = new Set()
      for (const a of args.slice(1)) {
        if (!candidates.includes(a)) fail0(n, `unknown candidate ${a}`)
        if (seen.has(a)) fail0(n, `candidate ${a} is repeated`)
        seen.add(a)
      }
      ballots.push({ count: BigInt(args[0]), ranking: args.slice(1) })
    } else {
      fail0(n, `unknown directive ${word}`)
    }
  })
  if (candidates === null) throw fail('error: no candidates')
  return { candidates, ballots }
}

function fail0(n, msg) {
  throw fail(`error: line ${n}: ${msg}`)
}
EOF
cat > src/count.js <<'EOF'
const byCode = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

export function count({ candidates, ballots }, mode) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const out = []
  let round = 0
  for (;;) {
    round++
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    for (const b of ballots) {
      const pick = b.ranking.find((c) => continuing.has(c))
      if (pick !== undefined) {
        votes.set(pick, votes.get(pick) + b.count)
        active += b.count
      }
    }
    let total = 0n
    for (const b of ballots) total += b.count
    for (const [c, v] of votes) history.get(c).push(v)
    const listed = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : byCode(a[0], b[0])))
    const line = `round ${round}: ${listed.map(([c, v]) => `${c}=${v}`).join(' ')} exhausted=${total - active}`
    if (mode === 'rounds') out.push(line)
    if (active === 0n) { out.push('no winner'); break }
    const win = listed.find(([, v]) => v * 2n > active)
    if (win) { out.push(`winner ${win[0]}`); break }
    let min = listed[listed.length - 1][1]
    let tied = listed.filter(([, v]) => v === min).map(([c]) => c)
    for (let r = 0; tied.length > 1 && r < round; r++) {
      const vals = tied.map((c) => history.get(c)[r])
      const m = vals.reduce((a, b) => (a < b ? a : b))
      if (vals.some((v) => v !== m)) {
        tied = tied.filter((c) => history.get(c)[r] === m)
        r = -1
      }
    }
    const gone = tied.sort(byCode)[tied.length - 1]
    continuing.delete(gone)
    if (mode === 'rounds') out.push(`eliminated ${gone}`)
  }
  if (mode === 'tally') out.unshift(`rounds ${round}`)
  return out.join('\n') + '\n'
}
EOF
